    for cell in row:
        if cell.value is not None:
            print(f"  {cell.coordinate}: {cell.value}")

# Now open with data_only=True to see computed values
wb_data = openpyxl.load_workbook('./summary.xlsx', data_only=True)
ws_data = wb_data['Summary']
print("\n=== Summary Sheet (computed values) ===")
for row in ws_data.iter_rows(min_row=1, max_row=5, max_col=4, values_only=False):
    for cell in row:
        if cell.value is not None:
            print(f"  {cell.coordinate}: {cell.value}")

# Also verify Segment Results sheet has correct data
ws_sr = wb_data['Segment Results']
print("\n=== Segment Results (computed) ===")
for r in range(9, 29):
    for c in range(1, 12):
        val = ws_sr.cell(row=r, column=c).value
        if val is not None:
            print(f"  {ws_sr.cell(row=r, column=c).coordinate}: {val}")"}

{"code": "import openpyxl

# Verify original sheets data matches
src_wb = openpyxl.load_workbook('./materials/FinancialStatementFY26Q4.xlsx')
dst_wb = openpyxl.load_workbook('./summary.xlsx', data_only=False)

for name in src_wb.sheetnames:
    src_ws = src_wb[name]
    dst_ws = dst_wb[name]
    mismatch = False
    for row in src_ws.iter_rows(min_row=1, max_row=src_ws.max_row, max_col=src_ws.max_column):
        for cell in row:
            dst_val = dst_ws.cell(row=cell.row, column=cell.column).value
            if cell.value != dst_val:
                print(f"MISMATCH in '{name}' at {cell.coordinate}: src={cell.value}, dst={dst_val}")
                mismatch = True
                break
        if mismatch:
            break
    if not mismatch:
        print(f"Sheet '{name}': all data matches OK")

print("\nAll original sheets verified.")"}
